    func test_push_status() {
        XCTAssertEqual(PushStatusCopy.apnsRefused, "Allowed, but Apple did not issue a token for this device. Restart the app; if it persists, contact support.", "push_status.apns_refused")
        XCTAssertEqual(PushStatusCopy.denied, "Turned off. Allow notifications for District AI in System Settings to receive calls and messages.", "push_status.denied")
        XCTAssertEqual(PushStatusCopy.notAsked, "Not set up on this device yet.", "push_status.not_asked")
        XCTAssertEqual(PushStatusCopy.notAttempted, "Allowed. Setting up this device.", "push_status.not_attempted")
        XCTAssertEqual(PushStatusCopy.refused(5), "Allowed, but District AI refused to set up this device (error 5). Contact support if it continues.", "push_status.refused")
        XCTAssertEqual(PushStatusCopy.registered, "Allowed. This device is set up to receive calls and messages.", "push_status.registered")
        XCTAssertEqual(PushStatusCopy.sessionExpired, "Allowed, but your session has expired. Sign out and sign in again.", "push_status.session_expired")
        XCTAssertEqual(PushStatusCopy.title, "Notifications", "push_status.title")
        XCTAssertEqual(PushStatusCopy.tooManyAttempts, "Allowed, but too many attempts were made. This will retry shortly.", "push_status.too_many_attempts")
        XCTAssertEqual(PushStatusCopy.unavailable, "This device could not be asked for permission. Try again, or restart the app.", "push_status.unavailable")
        XCTAssertEqual(PushStatusCopy.unreachable, "Allowed, but this device could not reach District AI. Check your connection.", "push_status.unreachable")
        L10nRuntime.withLocale(.frCA) {
            XCTAssertEqual(PushStatusCopy.apnsRefused, "Autorisées, mais Apple n'a pas émis de jeton pour cet appareil. Redémarrez l'application; si cela persiste, communiquez avec le soutien.", "push_status.apns_refused")
            XCTAssertEqual(PushStatusCopy.denied, "Désactivées. Pour recevoir appels et messages, il faut autoriser les notifications de District AI dans Réglages système.", "push_status.denied")
            XCTAssertEqual(PushStatusCopy.notAsked, "Appareil pas encore configuré.", "push_status.not_asked")
            XCTAssertEqual(PushStatusCopy.notAttempted, "Autorisées. Configuration de cet appareil.", "push_status.not_attempted")
            XCTAssertEqual(PushStatusCopy.refused(5), "Autorisées, mais District AI a refusé de configurer cet appareil (erreur 5). Communiquez avec le soutien si le problème persiste.", "push_status.refused")
            XCTAssertEqual(PushStatusCopy.registered, "Autorisées. Cet appareil est configuré pour recevoir les appels et les messages.", "push_status.registered")
            XCTAssertEqual(PushStatusCopy.sessionExpired, "Autorisées, mais votre session a expiré. Déconnectez-vous, puis reconnectez-vous.", "push_status.session_expired")
            XCTAssertEqual(PushStatusCopy.title, "Notifications", "push_status.title")
            XCTAssertEqual(PushStatusCopy.tooManyAttempts, "Autorisées, mais il y a eu trop de tentatives. Une nouvelle tentative suivra sous peu.", "push_status.too_many_attempts")
            XCTAssertEqual(PushStatusCopy.unavailable, "Impossible de demander l'autorisation sur cet appareil. Réessayez ou redémarrez l'application.", "push_status.unavailable")
            XCTAssertEqual(PushStatusCopy.unreachable, "Autorisées, mais cet appareil n'a pas pu joindre District AI. Vérifiez votre connexion.", "push_status.unreachable")
        }
    }

