    func test_scheduling_failure() {
        XCTAssertEqual(SchedulingFailureCopy.forbidden, "You can view this but not change it.", "scheduling_failure.forbidden")
        XCTAssertEqual(SchedulingFailureCopy.notReady, "Scheduling is not set up for this workspace yet.", "scheduling_failure.not_ready")
        XCTAssertEqual(SchedulingFailureCopy.offline, "You appear to be offline. Check your connection and try again.", "scheduling_failure.offline")
        XCTAssertEqual(SchedulingFailureCopy.slotTaken, "That time was just taken. Pick another.", "scheduling_failure.slot_taken")
        XCTAssertEqual(SchedulingFailureCopy.staleBuild, "This version of the app could not read that response. Please update.", "scheduling_failure.stale_build")
        XCTAssertEqual(SchedulingFailureCopy.unavailable, "The booking system did not answer. Try again in a minute.", "scheduling_failure.unavailable")
        XCTAssertEqual(SchedulingFailureCopy.unknown, "That did not save. Try again.", "scheduling_failure.unknown")
        L10nRuntime.withLocale(.frCA) {
            XCTAssertEqual(SchedulingFailureCopy.forbidden, "Vous pouvez consulter ceci, mais pas le modifier.", "scheduling_failure.forbidden")
            XCTAssertEqual(SchedulingFailureCopy.notReady, "La prise de rendez-vous n'est pas encore configurée pour cet espace de travail.", "scheduling_failure.not_ready")
            XCTAssertEqual(SchedulingFailureCopy.offline, "Vous semblez être hors ligne. Vérifiez votre connexion et réessayez.", "scheduling_failure.offline")
            XCTAssertEqual(SchedulingFailureCopy.slotTaken, "Cette heure vient d'être prise. Choisissez-en une autre.", "scheduling_failure.slot_taken")
            XCTAssertEqual(SchedulingFailureCopy.staleBuild, "Cette version de l'app n'a pas pu lire cette réponse. Veuillez mettre l'app à jour.", "scheduling_failure.stale_build")
            XCTAssertEqual(SchedulingFailureCopy.unavailable, "Le système de réservation n'a pas répondu. Réessayez dans une minute.", "scheduling_failure.unavailable")
            XCTAssertEqual(SchedulingFailureCopy.unknown, "Rien n'a été enregistré. Réessayez.", "scheduling_failure.unknown")
        }
    }

