    func test_session() {
        XCTAssertEqual(SessionCopy.appearOfflineCheckConnection, "You appear to be offline. Check your connection and try again.", "session.appear_offline_check_connection")
        XCTAssertEqual(SessionCopy.degradedEveryRegion, "Your account is unchanged, but we could not reach every region. Please try again.", "session.degraded_every_region")
        XCTAssertEqual(SessionCopy.degradedNamedRegions("<regions>"), "Your account is unchanged, but we could not reach <regions>. Some workspaces are missing from this list.", "session.degraded_named_regions")
        XCTAssertEqual(SessionCopy.doNotHavePermission, "You do not have permission to do that in this workspace.", "session.do_not_have_permission")
        XCTAssertEqual(SessionCopy.interruptedRefresh, "Your session ended unexpectedly. Please sign in again.", "session.interrupted_refresh")
        XCTAssertEqual(SessionCopy.markerNotDurable, "We could not safely refresh your session. Please try again.", "session.marker_not_durable")
        XCTAssertEqual(SessionCopy.noLongerAvailable, "That is no longer available.", "session.no_longer_available")
        XCTAssertEqual(SessionCopy.refreshNotSent, "You appear to be offline. Your session is still active.", "session.refresh_not_sent")
        XCTAssertEqual(SessionCopy.refreshRejected, "Your session is no longer valid. Please sign in again.", "session.refresh_rejected")
        XCTAssertEqual(SessionCopy.refreshThrottled, "Too many requests. Please try again shortly.", "session.refresh_throttled")
        XCTAssertEqual(SessionCopy.refreshTokenExpired, "You have been signed out after 60 days. Please sign in again.", "session.refresh_token_expired")
        XCTAssertEqual(SessionCopy.refreshUnreachable, "We could not confirm your session. Please sign in again.", "session.refresh_unreachable")
        XCTAssertEqual(SessionCopy.requestCouldNotCompleted, "That request could not be completed.", "session.request_could_not_completed")
        XCTAssertEqual(SessionCopy.sessionHasEndedPlease, "Your session has ended. Please sign in again.", "session.session_has_ended_please")
        XCTAssertEqual(SessionCopy.signInExpired, "That sign-in expired. Please try again.", "session.sign_in_expired")
        XCTAssertEqual(SessionCopy.signInNotCompleted("<reason>"), "Sign-in was not completed (<reason>).", "session.sign_in_not_completed")
        XCTAssertEqual(SessionCopy.signInNotVerified, "That sign-in could not be verified. Please try again.", "session.sign_in_not_verified")
        XCTAssertEqual(SessionCopy.signedOut, "You are signed out.", "session.signed_out")
        XCTAssertEqual(SessionCopy.somethingWentWrongOur, "Something went wrong on our side. Please try again.", "session.something_went_wrong_our")
        XCTAssertEqual(SessionCopy.storeUnavailable, "We could not read your saved session. Please try again.", "session.store_unavailable")
        XCTAssertEqual(SessionCopy.tooManyAttempts, "Too many attempts. Please try again shortly.", "session.too_many_attempts")
        XCTAssertEqual(SessionCopy.unreachable, "We could not reach District AI. Check your connection.", "session.unreachable")
        XCTAssertEqual(SessionCopy.versionAppCouldNot, "This version of the app could not read that response. Please update.", "session.version_app_could_not")
        XCTAssertEqual(SessionCopy.workspaceSSubscriptionNot, "This workspace's subscription is not active.", "session.workspace_s_subscription_not")
        L10nRuntime.withLocale(.frCA) {
            XCTAssertEqual(SessionCopy.appearOfflineCheckConnection, "Vous semblez être hors ligne. Vérifiez votre connexion et réessayez.", "session.appear_offline_check_connection")
            XCTAssertEqual(SessionCopy.degradedEveryRegion, "Votre compte est inchangé, mais au moins une région est injoignable. Veuillez réessayer.", "session.degraded_every_region")
            XCTAssertEqual(SessionCopy.degradedNamedRegions("<regions>"), "Votre compte est inchangé, mais certaines régions n'ont pas répondu (<regions>). Il manque des espaces de travail dans la liste.", "session.degraded_named_regions")
            XCTAssertEqual(SessionCopy.doNotHavePermission, "Vous n'avez pas la permission de faire cela dans cet espace de travail.", "session.do_not_have_permission")
            XCTAssertEqual(SessionCopy.interruptedRefresh, "Votre session a pris fin de façon imprévue. Veuillez vous reconnecter.", "session.interrupted_refresh")
            XCTAssertEqual(SessionCopy.markerNotDurable, "Le renouvellement sécurisé de votre session a échoué. Veuillez réessayer.", "session.marker_not_durable")
            XCTAssertEqual(SessionCopy.noLongerAvailable, "Cet élément n'est plus disponible.", "session.no_longer_available")
            XCTAssertEqual(SessionCopy.refreshNotSent, "Vous semblez être hors ligne. Votre session est toujours active.", "session.refresh_not_sent")
            XCTAssertEqual(SessionCopy.refreshRejected, "Votre session n'est plus valide. Veuillez vous reconnecter.", "session.refresh_rejected")
            XCTAssertEqual(SessionCopy.refreshThrottled, "Trop de requêtes. Veuillez réessayer sous peu.", "session.refresh_throttled")
            XCTAssertEqual(SessionCopy.refreshTokenExpired, "Votre session a été fermée après 60 jours. Veuillez vous reconnecter.", "session.refresh_token_expired")
            XCTAssertEqual(SessionCopy.refreshUnreachable, "Nous n'avons pas pu confirmer votre session. Veuillez vous reconnecter.", "session.refresh_unreachable")
            XCTAssertEqual(SessionCopy.requestCouldNotCompleted, "Cette requête n'a pas pu être traitée.", "session.request_could_not_completed")
            XCTAssertEqual(SessionCopy.sessionHasEndedPlease, "Votre session a pris fin. Veuillez vous reconnecter.", "session.session_has_ended_please")
            XCTAssertEqual(SessionCopy.signInExpired, "Cette tentative de connexion a expiré. Veuillez réessayer.", "session.sign_in_expired")
            XCTAssertEqual(SessionCopy.signInNotCompleted("<reason>"), "La connexion n'a pas abouti (<reason>).", "session.sign_in_not_completed")
            XCTAssertEqual(SessionCopy.signInNotVerified, "Cette connexion n'a pas pu être vérifiée. Veuillez réessayer.", "session.sign_in_not_verified")
            XCTAssertEqual(SessionCopy.signedOut, "Déconnexion effectuée.", "session.signed_out")
            XCTAssertEqual(SessionCopy.somethingWentWrongOur, "Une erreur est survenue de notre côté. Veuillez réessayer.", "session.something_went_wrong_our")
            XCTAssertEqual(SessionCopy.storeUnavailable, "Impossible de lire votre session sauvegardée. Veuillez réessayer.", "session.store_unavailable")
            XCTAssertEqual(SessionCopy.tooManyAttempts, "Trop de tentatives. Veuillez réessayer sous peu.", "session.too_many_attempts")
            XCTAssertEqual(SessionCopy.unreachable, "Impossible de joindre District AI. Vérifiez votre connexion Internet.", "session.unreachable")
            XCTAssertEqual(SessionCopy.versionAppCouldNot, "Cette version de l'app n'a pas pu lire cette réponse. Veuillez mettre l'app à jour.", "session.version_app_could_not")
            XCTAssertEqual(SessionCopy.workspaceSSubscriptionNot, "L'abonnement de cet espace de travail n'est pas actif.", "session.workspace_s_subscription_not")
        }
    }

